// Validation for user-supplied MCP endpoint URLs, so the SSRF blocklist has one definition. A
// gatekeeper pointed at an administrator-configured URL has no untrusted input to check.

import { fetchOptions, type InsecureEnv } from "./fetch.js";

/** Result of validating a user-supplied endpoint. */
export type EndpointValidation = { ok: true; url: string } | { ok: false; reason: string };

// Hostnames that must never be reachable from a user-supplied endpoint.
//
// This is a literal/suffix check and is deliberately not the security boundary: a Worker cannot
// resolve DNS, so it cannot see through a public hostname that resolves -- or rebinds -- to a
// private address. Enforcement is `global_fetch_strictly_public` (set in each connector's
// wrangler.jsonc), which makes workerd reject reserved IP ranges after resolution, on every request
// and every redirect hop. What this list adds is a legible refusal at connect time, naming the
// problem while the user is still looking at the form they typed the URL into.
const BLOCKED_HOST_PATTERNS = [
  /^localhost$/i,
  /\.localhost$/i,
  /^127\./,

display.text:
// Validation for user-supplied MCP endpoint URLs, so the SSRF blocklist has one definition. A
// gatekeeper pointed at an administrator-configured URL has no untrusted input to check.

import { fetchOptions, type InsecureEnv } from "./fetch.js";

/** Result of validating a user-supplied endpoint. */
export type EndpointValidation = { ok: true; url: string } | { ok: false; reason: string };

// Hostnames that must never be reachable from a user-supplied endpoint.
//
// This is a literal/suffix check and is deliberately not the security boundary: a Worker cannot
// resolve DNS, so it cannot see through a public hostname that resolves -- or rebinds -- to a
// private address. Enforcement is `global_fetch_strictly_public` (set in each connector's
// wrangler.jsonc), which makes workerd reject reserved IP ranges after resolution, on every request
// and every redirect hop. What this list adds is a legible refusal at connect time, naming the
// problem while the user is still looking at the form they typed the URL into.
const BLOCKED_HOST_PATTERNS = [
  /^localhost$/i,
  /\.localhost$/i,
  /^127\./,
  /^0\./,
  /^10\./,
  /^192\.168\./,
  /^172\.(1[6-9]|2[0-9]|3[01])\./,
  /^169\.254\./,
  /^\[?::1\]?$/,
  /^\[?f[cd][0-9a-f]{2}:/i,
  /^metadata\./i,
  /\.internal$/i,
];

// Rewrites a hostname into the form the blocklist is written against. `new URL()` accepts several
// spellings of the same address: `http://2130706433/` and `http://0x7f000001/` are both 127.0.0.1,
// and `[::ffff:127.0.0.1]` is its IPv4-mapped IPv6 form. Each becomes dotted-quad.
function normalizeHost(hostname: string): string {
  // `URL` rewrites an IPv4-mapped IPv6 address into hex groups, so `[::ffff:127.0.0.1]` arrives as
  // `[::ffff:7f00:1]` and the dotted-quad spelling is never what we see.
  const mapped = /^\[::ffff:([0-9a-f]{1,4}):([0-9a-f]{1,4})\]$/i.exec(hostname);
  if (mapped) {
    const [high, low] = [parseInt(mapped[1], 16), parseInt(mapped[2], 16)];
    return [high >>> 8, high & 0xff, low >>> 8, low & 0xff].join(".");
  }

  // A bare integer (decimal, hex, or octal) is a valid IPv4 address to most resolvers.
  const asInteger = /^(?:0[xX][0-9a-fA-F]+|0[0-7]*|[1-9][0-9]*)$/.test(hostname)
    ? Number(hostname)
    : NaN;
  if (Number.isInteger(asInteger) && asInteger >= 0 && asInteger <= 0xffffffff) {
    return [24, 16, 8, 0].map(shift => (asInteger >>> shift) & 0xff).join(".");
  }
  return hostname;
}

/**
 * Whether a host must never be fetched on behalf of a user-supplied endpoint. Exported because the
 * endpoint the user typed is not the only URL its server can make us fetch: OAuth discovery follows
 * a `WWW-Authenticate` header and then an issuer, both chosen by the far side.
 */
export function isBlockedHost(hostname: string): boolean {
  const host = normalizeHost(hostname);
  return BLOCKED_HOST_PATTERNS.some(pattern => pattern.test(host));
}

/**
 * Validates and canonicalizes a user-supplied MCP endpoint.
 *
 * Requires HTTPS and rejects private/link-local/metadata hosts. `MCP_ALLOW_INSECURE` disables both
 * checks for local development, allowing HTTP and otherwise-blocked hosts.
 */
export function validateCustomEndpoint(env: InsecureEnv, input: string): EndpointValidation {
  const trimmed = input.trim();
  if (!trimmed) return { ok: false, reason: "Enter the MCP server's endpoint URL." };

  let url: URL;
  try {
    url = new URL(trimmed);
  } catch {
    return { ok: false, reason: "That is not a valid URL." };
  }

  const insecureAllowed = fetchOptions(env).allowInsecure === true;
  if (url.protocol !== "https:" && !(insecureAllowed && url.protocol === "http:")) {
    return { ok: false, reason: "The endpoint must use https://." };
  }
  if (!insecureAllowed && isBlockedHost(url.hostname)) {
    return { ok: false, reason: "That host is not reachable from Cloudflare OS." };
  }

  // Credentials in the URL would end up in logs and approval prompts.
  if (url.username || url.password) {
    return { ok: false, reason: "Remove the username and password from the URL." };
  }

  url.hash = "";
  return { ok: true, url: url.toString() };
}

metadata.preview:
// Talking to an MCP endpoint through an account's stored credentials. Every call a connector makes
// goes through `withClient`, so the transport-session lifecycle lives in one place.
//
// A lapsed transport session is re-established and the call retried once, but only for reads. The
// MCP spec says a 404 on a session-bearing request means the session is gone, implying the request
// was never dispatched, but a 404 from something in front of the server could arrive after the call
// landed. A write is left to fail as outcome-unknown; its approved action is closed, and a person
// must deliberately stage a new one after checking whether the first took effect.

import {
  McpAuthRequiredError,
  McpCallNotDispatchedError,
  McpClient,
  McpSessionExpiredError,
  type McpToolFilter,
  type ToolCatalog,
}
  from "./client.js";
import { fetchOptions, type InsecureEnv } from "./fetch.js";
import { MAX_TOOLS_PER_SERVER } from "./tools.js";

display.text:
// Talking to an MCP endpoint through an account's stored credentials. Every call a connector makes
// goes through `withClient`, so the transport-session lifecycle lives in one place.
//
// A lapsed transport session is re-established and the call retried once, but only for reads. The
// MCP spec says a 404 on a session-bearing request means the session is gone, implying the request
// was never dispatched, but a 404 from something in front of the server could arrive after the call
// landed. A write is left to fail as outcome-unknown; its approved action is closed, and a person
// must deliberately stage a new one after checking whether the first took effect.

import {
  McpAuthRequiredError,
  McpCallNotDispatchedError,
  McpClient,
  McpSessionExpiredError,
  type McpToolFilter,
  type ToolCatalog,
}
  from "./client.js";
import { fetchOptions, type InsecureEnv } from "./fetch.js";
import { MAX_TOOLS_PER_SERVER } from "./tools.js";

/** The environment this module reads. Each Worker's own `Env` satisfies it structurally. */
export type ConnectionEnv = InsecureEnv & {
  /** Name this deployment reports to MCP servers during `initialize`. */
  MCP_CLIENT_NAME?: string;
};

export type WithClientOptions = {
  /** False for a call that may have taken effect, so a dropped session is not retried. See above. */
  retryOnExpiry?: boolean;
  /** Absolute deadline shared with time spent waiting for a discovery slot. */
  deadline?: number;
};

/**
 * Everything an account must hand over before a request can be made. One value rather than two
 * getters: every MCP request needs both, and asking separately costs two serialized round trips to
 * the account Durable Object.
 */
export type McpConnection = {
  /** Bearer token, or null for a public server. */
  authorization: string | null;
  /** Transport session id from a previous `initialize`, if one is cached. */
  sessionId: string | null;
  /**
   * Persisted account generation. Every state write after an await returns this to the account, so
   * work started before a reconnect cannot overwrite the new connection's tokens or session.
   */
  generation: number;
};

/**
 * The part of an account Durable Object that a call needs, structural so this module does not depend
 * on either connector's `McpAccount`.
 */
export type ConnectionAccount = {
  /**
   * `endpoint` binds the credential response to where the caller will send it. An account may be
   * repointed while an older facet still exists; returning current credentials to that facet would
   * send the new server's bearer token to the old server.
   */
  getConnection(endpoint: string): Promise<McpConnection>;
  assertConnectionCurrent(endpoint: string, generation: number): Promise<void>;
  setMcpSessionId(
    endpoint: string,
    generation: number,
    previousSessionId: string | null,
    sessionId: string | null,
  ): Promise<boolean>;
  noteCredentialsExpired(endpoint: string, generation: number): Promise<void>;
};

/** The name this deployment gives when introducing itself to an MCP server. */
export function clientName(env: ConnectionEnv): string {
  return env.MCP_CLIENT_NAME ?? "Gadgets";
}

function notDispatched(err: unknown): McpCallNotDispatchedError {
  if (err instanceof McpCallNotDispatchedError) return err;
  return new McpCallNotDispatchedError(
    err instanceof Error ? err.message : String(err),
    err,
  );
}

/** Runs `fn` against an initialized client for `endpoint`, using the account's credentials. */
export async function withClient<T>(
  env: ConnectionEnv,
  account: ConnectionAccount,
  endpoint: string,
  fn: (client: McpClient) => Promise<T>,
  options: WithClientOptions = {},
): Promise<T> {
  // Read once for the whole operation. The account refreshes a token a minute before expiry, so one
  // valid here stays valid for the handful of requests a single `withClient` makes.
  let connection: McpConnection;
  try {
    connection = await account.getConnection(endpoint);
  } catch (err) {
    throw notDispatched(err);
  }
  const { authorization, sessionId, generation } = connection;
  const client = new McpClient(
    endpoint, async method => {
      if (method === "tools/call") {
        await account.assertConnectionCurrent(endpoint, generation);
      }
      return authorization;
    }, sessionId, {
      ...fetchOptions(env),
      deadline: options.deadline,
    });
  let persistedSessionId = sessionId;

  const persistSession = async (): Promise<void> => {
    if (client.sessionId === persistedSessionId) return;
    const accepted = await account.setMcpSessionId(
      endpoint, generation, persistedSessionId, client.sessionId);
    if (!accepted) {
      await client.closeSession().catch(() => undefined);
      throw new McpCallNotDispatchedError(
        "Another request replaced this MCP transport session. Try again.");
    }
    persistedSessionId = client.sessionId;
  };

  const initialize = async (): Promise<void> => {
    await client.initialize(clientName(env));
    await persistSession();
  };

  const rejectCredentials = async (err: McpAuthRequiredError): Promise<never> => {
    const rejected = new Error(
      "The MCP server rejected this connection's credentials. Please reconnect the account.",
      { cause: err });
    let cause: unknown = rejected;
    try {
      await account.noteCredentialsExpired(endpoint, generation);
    } catch (notificationError) {
      cause = new AggregateError(
        [rejected, notificationError],
        "The credentials were rejected and their expiry notification failed.",
      );
    }
    throw new McpCallNotDispatchedError(rejected.message, cause);
  };

  try {
    if (!sessionId) {
      try {
        await initialize();
      } catch (err) {
        // Let the outer handler record credential rejection. Every other initialization failure is
        // known to precede the requested tool call.
        if (err instanceof McpAuthRequiredError) throw err;
        throw notDispatched(err);
      }
    }
    try {
      return await fn(client);
    } catch (err) {
      if (!(err instanceof McpSessionExpiredError)) throw err;
      if (options.retryOnExpiry !== false) {
        client.sessionId = null;
        try {
          await initialize();
        } catch (initializeError) {
          if (initializeError instanceof McpAuthRequiredError) throw initializeError;
          throw notDispatched(initializeError);
        }
        return await fn(client);
      }
      // This call is not retried, since it may already have taken effect. The session is gone all
      // the same, so the cached id is dead: left in place it would fail every later call for a
      // reason already known, including the retry the Workshop offers the user. Clearing it makes
      // the next call re-initialize.
      if (persistedSessionId) {
        await account.setMcpSessionId(endpoint, generation, persistedSessionId, null);
      }
      throw err;
    }
  } catch (err) {
    if (err instanceof McpAuthRequiredError) {
      return rejectCredentials(err);
    }
    throw err;
  }
}

/**
 * Lists an endpoint's tools, bounded by `MAX_TOOLS_PER_SERVER`. Reports whether a cap cut the
 * listing short, since callers infer what the endpoint is from what it does and does not offer.
 */
export async function fetchTools(
  env: ConnectionEnv,
  account: ConnectionAccount,
  endpoint: string,
  include?: McpToolFilter,
  options?: WithClientOptions,
): Promise<ToolCatalog> {
  return withClient(env, account, endpoint,
    client => client.listTools(MAX_TOOLS_PER_SERVER, include), options);
}

metadata.preview:
// The described tool catalog of one binding: fetched, cached, scoped, and classified. A broad grant
// can cover definitions omitted by this bounded catalog; `HydratedTools` remembers those when the
// facet discovers them directly from the endpoint.
//
// The cache is per gatekeeper facet, so per binding rather than per account. That wastes
// `tools/list` calls, but a shared cache would be a channel between two otherwise unrelated
// bindings, and a scoped grant is meant not to see what a wider one fetched.

import { isValidToolName, type McpTool } from "./client.js";
import { fetchTools, type ConnectionAccount, type ConnectionEnv } from "./connection.js";
import { looksLikePortal, toolBelongsToServer } from "./portal.js";
import { scopeAllows, type ToolScope } from "./scope.js";
import type { McpLog } from "./log.js";
import {
  catalogRevision,
  classifyTool,
  MAX_TOOLS_PER_SERVER,
  type ClassifiedTool,
  type ServerTrust,
} from "./tools.js";

display.text:
// The described tool catalog of one binding: fetched, cached, scoped, and classified. A broad grant
// can cover definitions omitted by this bounded catalog; `HydratedTools` remembers those when the
// facet discovers them directly from the endpoint.
//
// The cache is per gatekeeper facet, so per binding rather than per account. That wastes
// `tools/list` calls, but a shared cache would be a channel between two otherwise unrelated
// bindings, and a scoped grant is meant not to see what a wider one fetched.

import { isValidToolName, type McpTool } from "./client.js";
import { fetchTools, type ConnectionAccount, type ConnectionEnv } from "./connection.js";
import { looksLikePortal, toolBelongsToServer } from "./portal.js";
import { scopeAllows, type ToolScope } from "./scope.js";
import type { McpLog } from "./log.js";
import {
  catalogRevision,
  classifyTool,
  MAX_TOOLS_PER_SERVER,
  type ClassifiedTool,
  type ServerTrust,
} from "./tools.js";

/** How long a fetched tool catalog is reused before the server is asked again. */
export const CATALOG_TTL_MS = 5 * 60 * 1000;

// Cached tool catalog plus the revision it was fetched at.
type CachedCatalog = {
  tools: McpTool[];
  revision: string;
  fetchedAt: number;
  // Whether a cap cut the listing short. Cached with the tools because `looksLikePortal` runs on
  // every call, including the ones served from here, and a flag left behind on the fetch path would
  // make an endpoint's portal-ness flip as soon as the cache was hit.
  truncated?: boolean;
};

/**
 * The key-value storage a facet lends this module. Structural so it does not depend on either
 * connector's Durable Object type; `ctx.storage.kv` satisfies it.
 */
export interface CatalogStore {
  get<T>(key: string): T | undefined;
  put<T>(key: string, value: T): void;
}

/** What resolving a catalog needs. Everything here is owned by the calling facet. */
export type CatalogRequest = {
  store: CatalogStore;
  log: McpLog;
  env: ConnectionEnv;
  account: ConnectionAccount;
  endpoint: string;
  /** How much of the endpoint this binding may call. */
  scope: ToolScope;
  /**
   * Read from the deployment's current configuration on every call, never from stored account
   * state, so withdrawing the tier takes effect without a reconnect. See `ServerTrust`.
   */
  trust: ServerTrust;
  /** Absolute deadline shared with the facet operation that requested this catalog. */
  deadline?: number;
};

/** A binding's currently described tools and whether their endpoint is a portal. */
export type ScopedCatalog = {
  /** Scoped and classified definitions retained in the bounded catalog. */
  tools: ClassifiedTool[];
  /** Whether the endpoint is known or conservatively assumed to be a portal. */
  isPortal: boolean;
  /** False when this catalog proves an absent tool name does not exist. */
  truncated: boolean;
};

/**
 * Returns the tools this binding may call and its endpoint kind, refreshing stale cached data.
 *
 * A changed catalog is adopted rather than pinned, since refusing to see new tools would break
 * working Gadgets, but the change is logged and a scoped binding cannot widen: a tool list is a set
 * of names and a server scope is a name prefix.
 */
export async function scopedCatalog(request: CatalogRequest): Promise<ScopedCatalog> {
  const cached = request.store.get<CachedCatalog>("catalog");
  let tools = cached?.tools;
  let truncated = cached?.truncated ?? false;

  if (!cached || Date.now() - cached.fetchedAt > CATALOG_TTL_MS) {
    try {
      const serverId = request.scope.serverId;
      const fetched = await fetchTools(
        request.env,
        request.account,
        request.endpoint,
        serverId ? tool => toolBelongsToServer(tool.name, serverId) : undefined,
        { deadline: request.deadline },
      );
      const revision = await catalogRevision(fetched.tools);
      if (cached && cached.revision !== revision) {
        request.log.info("server tool catalog changed", {
          event: "catalog.changed", catalogRevision: revision, toolCount: fetched.tools.length,
        });
      }
      tools = fetched.tools;
      truncated = fetched.truncated;
      try {
        request.store.put<CachedCatalog>("catalog", {
          tools, revision, fetchedAt: Date.now(), truncated,
        });
      } catch (err) {
        // The client leaves 32 KiB below the documented per-value limit, but storage serialization
        // is not JSON and its overhead is not an API guarantee. A cache is an optimization: if the
        // runtime still rejects this value, use the fresh catalog now rather than turning a useful
        // server response into a failed operation. The next call will fetch it again.
        request.log.warn("could not cache tool catalog", {
          event: "catalog.cache.write.failed", error: err,
        });
      }
    } catch (err) {
      // Serve the last known catalog rather than breaking a running Gadget on a transient failure.
      if (!tools) throw err;
      request.log.warn("could not refresh tool catalog", {
        event: "catalog.refresh.failed", error: err,
      });
    }
  }

  // Whether the endpoint is a portal is read from the full list, before scoping hides the `portal_*`
  // tools that are the evidence.
  const all = tools ?? [];
  // A server-scoped grant can only be minted by the portal connector, and its filtered listing no
  // longer contains the `portal_list_servers` that `looksLikePortal` looks for. Deciding from the
  // scope first is what keeps the `portal_*` exclusion in force: without it, a `#server=portal`
  // grant would filter down to exactly the portal's own tools, find no evidence of a portal, and let
  // a Gadget call `portal_toggle_servers` to widen its own reach.
  const isPortal = request.scope.serverId !== undefined
    || looksLikePortal(all, { truncated, cap: MAX_TOOLS_PER_SERVER });
  return {
    isPortal,
    truncated,
    tools: all
      .filter(tool => scopeAllows(request.scope, tool.name, isPortal))
      .map(tool => classifyTool(tool, request.trust)),
  };
}

/**
 * Memory-only cache for definitions fetched beyond a binding's bounded catalog.
 *
 * Broad grants may cover tools past the catalog cut, so definitions and absences are remembered for
 * one TTL to avoid repeating a paginated lookup on every call.
 */
export class HydratedTools {
  // Insertion-ordered, which is what makes the eviction below the oldest entry.
  #entries = new Map<string, { fetchedAt: number; tool: McpTool | null; bytes: number }>();
  #loads = new Map<string, Promise<McpTool | undefined>>();
  #totalBytes = 0;

  /** Maximum definitions and remembered absences retained per facet activation. */
  static readonly MAX_ENTRIES = MAX_TOOLS_PER_SERVER;
  /** Aggregate retained definition budget per facet activation. */
  static readonly MAX_BYTES = 1024 * 1024;

  #fresh(name: string): { tool: McpTool | null } | undefined {
    const cached = this.#entries.get(name);
    if (!cached) return undefined;
    if (Date.now() - cached.fetchedAt > CATALOG_TTL_MS) {
      this.#entries.delete(name);
      this.#totalBytes -= cached.bytes;
      return undefined;
    }
    return cached;
  }

  #remember(name: string, tool: McpTool | null): void {
    const existing = this.#entries.get(name);
    if (existing) {
      this.#entries.delete(name);
      this.#totalBytes -= existing.bytes;
    }
    const bytes = new TextEncoder().encode(JSON.stringify(tool)).byteLength;
    while (this.#entries.size >= HydratedTools.MAX_ENTRIES
        || this.#totalBytes + bytes > HydratedTools.MAX_BYTES) {
      const oldest = this.#entries.keys().next();
      if (oldest.done) break;
      const removed = this.#entries.get(oldest.value);
      this.#entries.delete(oldest.value);
      this.#totalBytes -= removed?.bytes ?? 0;
    }
    if (bytes > HydratedTools.MAX_BYTES) return;
    this.#entries.set(name, { fetchedAt: Date.now(), tool, bytes });
    this.#totalBytes += bytes;
  }

  #load(
    name: string,
    load: (name: string) => Promise<McpTool | undefined>,
  ): Promise<McpTool | undefined> {
    const existing = this.#loads.get(name);
    if (existing) return existing;
    if (this.#loads.size >= HydratedTools.MAX_ENTRIES) {
      throw new Error("Too many MCP tool definitions are already loading.");
    }

    const pending = load(name).then(loaded => {
      this.#remember(name, loaded ?? null);
      return loaded;
    }).finally(() => {
      if (this.#loads.get(name) === pending) this.#loads.delete(name);
    });
    this.#loads.set(name, pending);
    return pending;
  }

  /**
   * Returns the named tool, coalescing concurrent loads and caching a result for one TTL.
   *
   * `load` is expected to enforce the caller's scope: this cache is keyed by name alone and holds
   * whatever it is given, so it can neither widen nor narrow a grant. A failed load is not cached,
   * allowing a later call to recover from a transient endpoint failure.
   */
  async resolve(
    name: string,
    load: (name: string) => Promise<McpTool | undefined>,
  ): Promise<McpTool | undefined> {
    if (!isValidToolName(name)) return undefined;
    const cached = this.#fresh(name);
    if (cached) return cached.tool ?? undefined;
    return this.#load(name, load);
  }
}

