// Single-use secrets in the connect flow, and the timings that bound them.
//
// The connect handshake is reached over plain HTTP with no session of its own, so the URL path is
// the authorization: whoever holds the nonce is treated as the person who started the flow. Shared
// so a connector cannot quietly weaken the handshake with a shorter nonce or a longer lifetime.

import { hexEncode } from "./util.js";

/**
 * Length of a connect nonce. 32 bytes (64 hex characters) is far beyond guessing, and the connect
 * handler checks the encoded length before doing any work.
 */
export const NONCE_BYTES = 32;

/** How long a link handed to the user stays usable. Long enough to read, short enough to matter. */
export const INITIATION_NONCE_LIFETIME_MS = 10 * 60 * 1000;

/** How long an in-flight OAuth authorization may take before its state is discarded. */
export const OAUTH_NONCE_LIFETIME_MS = 10 * 60 * 1000;

/** Margin before an access token's stated expiry at which it is refreshed anyway. */
export const ACCESS_TOKEN_SAFETY_MS = 60 * 1000;

/**
 * Assumed access-token lifetime when the server states none. `expires_in` is optional per RFC 6749,
 * and an unknown expiry has to be treated as near rather than as never.
 */
export const DEFAULT_TOKEN_LIFETIME_S = 60 * 60;

/** How long an account that never finished connecting waits before deleting itself. */
export const CONNECT_TIMEOUT_MS = 60 * 60 * 1000;

export function generateNonce(): string {
  return hexEncode(crypto.getRandomValues(new Uint8Array(NONCE_BYTES)));
}

/**
 * Compares two hex-encoded nonces without leaking how far the match got.
 *
 * The length check is not a leak: nonce length is fixed and public.
 */
export function constantTimeEqual(a: string, b: string): boolean {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

// Entrypoint for the sandboxed Context Library iframe. All data flows through the host-injected
// ContextApi RPC capability.

import { createRoot } from 'react-dom/client'
import { TooltipProvider, Toasty } from '@cloudflare/kumo'
import { RpcTarget, newMessagePortRpcSession } from 'capnweb'
import type { RpcStub } from 'capnweb'
import type { ContextApi } from '../src/context-types'
import type {
  GatekeeperAppTheme,
  GatekeeperAppThemeReceiver,
} from '@gadgets/workshop-shared/theme'
import ContextLibraryPage from './ContextLibraryPage'
import { ContextApiProvider, PresentationProvider, type PresentAck } from './bridge'
import { applyAppTheme } from './theme'
import './styles.css'
import ErrorBoundary from './ErrorBoundary'
import { installErrorReporting, reportIssue } from './error-reporting'

installErrorReporting()

// The only capability the iframe exposes back to the host: a receiver for theme pushes.
class AppIframe extends RpcTarget implements GatekeeperAppThemeReceiver {
  setTheme(theme: GatekeeperAppTheme): void {
    applyAppTheme(theme)
  }
}

interface HostCapability extends RpcTarget {
  readonly ui: RpcStub<ContextApi>
  // Grow the iframe to a full-viewport overlay for app-level modals (`true`) or restore it (`false`).
  setPresenting(active: boolean): Promise<PresentAck>
  // Returns the current theme and calls back on `receiver` whenever it changes.
  subscribeTheme(receiver: GatekeeperAppThemeReceiver): Promise<GatekeeperAppTheme>
}

function main() {
  const root = document.getElementById('root')
  if (!root) throw new Error('missing #root')

  const { port1, port2 } = new MessageChannel()
  // Opaque-origin iframes can't name their parent origin. The parent accepts this handshake only from
  // this frame + null origin; the message only transfers a private port.
  window.parent.postMessage({ type: 'handshake' }, '*', [port2])
  const iframe = new AppIframe()
  const host = newMessagePortRpcSession<HostCapability>(port1, iframe)
  // The initial theme comes back from the call; later changes arrive via iframe.setTheme().
  host.subscribeTheme(iframe).then(applyAppTheme).catch(() => {})

  createRoot(root, {
    onUncaughtError: (error) => reportIssue('context.react-root', error, {
      handled: false, severity: 'fatal', captureMechanism: 'react',
    }),
  }).render(
    <ErrorBoundary><ContextApiProvider value={host.ui}>
      <PresentationProvider setPresenting={(active) => host.setPresenting(active)}>
        <TooltipProvider>
          <Toasty>
            <ContextLibraryPage />
          </Toasty>
        </TooltipProvider>
      </PresentationProvider>
    </ContextApiProvider></ErrorBoundary>,
  )
}

